package com.asmj.marketplace.product.repository;import com.asmj.marketplace.product.model.Product;import org.springframework.data.mongodb.repository.MongoRepository;import java.util.*;public interface ProductRepository extends MongoRepository<Product,String>{List<Product> findByActiveTrueAndApprovedTrueOrderByCreatedAtDesc();List<Product> findByVendorIdOrderByCreatedAtDesc(String vendorId);Optional<Product> findBySkuIgnoreCase(String sku);}
